const MOTION_BY_FUNC = new Map<number, BulletMotionInfo>();
for (const info of BULLET_MOTIONS) {
  MOTION_BY_FUNC.set(info.func, info);
}

export function bulletMotionInfo(func: number): BulletMotionInfo | undefined {
  return MOTION_BY_FUNC.get(func);
}

